head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25304";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — befLogin

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25304.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_befLogin", fn: function(){ return ((dma_pageContext.get("befLogin") ?? "") !== 'OK'); } }, { id: "if_befLogin_2", fn: function(){ return ((dma_pageContext.get("befLogin") ?? "") === 'OK'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_CROSSWEBEX_INSTALL_onclick
 * @description btn_CROSSWEBEX_INSTALL 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_CROSSWEBEX_INSTALL_onclick = function(e){
    try {
        CROSSWEBEX_INSTALL.download('crosswebex','client')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25304.btn_CROSSWEBEX_INSTALL_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name installCheckCallback
 * @description install Check Callback 처리
 * @param {*} result result
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.installCheckCallback = async function (result) {
    if (result) {
        await $c.win.alert(CROSSWEBEX_UTIL.loadStringTable().WARN.C_W_030);
        (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { /* TODO Stage2: [sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다) */ } })();
        $c.win.closePopup();
    } else {
        if (!CROSSWEBEX_CHECK.chkInfoStatus.status) {
            const info = CROSSWEBEX_CHECK.chkInfoStatus.info[0];
            if (CROSSWEBEX_UTIL.typeExtension()) {
                if (!info.extension) {
                    extDown.style.display = "block";
                } else {
                    extDown.style.display = "none";
                    cliDown.style.margin = "80px";
                }
            }
            if (!info.EX || !info.client) {
                if (CROSSWEBEX_UTIL.isLinux()) {
                    linuxDown.style.display = "block";
                } else {
                    cliDown.style.display = "block";
                }
            }
        }
    }
};
